for cfg in "375 812 ru" "812 375 ru" "820 1180 ru" "1440 900 ru" "1440 900 en" "375 812 en"; do set -- $cfg; W=$1 H=$2 LANG_UI=$3 timeout 300 node assets/raw/audit/h2/qa-h2.mjs > data/qa_$1_$3.json 2>&1; echo "== $1x$2 $3"; node -e "const j=JSON.parse(require('fs').readFileSync('data/qa_$1_$3.json','utf8'));for(const[k,v] of Object.entries(j.res)){const lat=v.latin.filter(t=>!/Hero |Iron Verdict|^Tab$/.test(t));if(v.lay.length||lat.length)console.log(k,JSON.stringify(v.lay),JSON.stringify(lat))}console.log('errors',j.errors)"; done
